<?php
require_once __DIR__.'/../includes/auth.php';
wajibRole('penghuni');
require_once __DIR__.'/../config/database.php';
require_once __DIR__.'/../includes/pembayaran_helper.php';
pastikanTagihanBulanIni($pdo);
if (empty($_SESSION['csrf_token'])) $_SESSION['csrf_token']=bin2hex(random_bytes(32));
$error=''; $success='';
$q=$pdo->prepare('SELECT p.id_penghuni,p.nama,p.id_kamar,k.nomor_kamar,k.harga_sewa FROM penghuni p LEFT JOIN kamar k ON k.id_kamar=p.id_kamar WHERE p.id_user=:id LIMIT 1');
$q->execute(['id'=>$_SESSION['id_user']]); $p=$q->fetch();
if(!$p){ exit('Data penghuni belum terhubung dengan akun ini.'); }

$periodeBulan=date('Y-m-01');
$periodeIso=date('Y-m');

if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['aksi']??'')==='ajukan'){
    $token=$_POST['csrf_token']??'';
    if(!hash_equals($_SESSION['csrf_token'],$token)) $error='Permintaan tidak valid. Silakan muat ulang halaman.';
    else {
        try {
            $cek=$pdo->prepare('SELECT id_pembayaran,status_pembayaran FROM pembayaran WHERE id_penghuni=:id AND (periode_sewa=:periode OR periode_sewa=:iso) ORDER BY id_pembayaran DESC LIMIT 1');
            $cek->execute(['id'=>$p['id_penghuni'],'periode'=>$periodeBulan,'iso'=>$periodeIso]); $sudah=$cek->fetch();
            if($sudah && $sudah['status_pembayaran']==='lunas'){
                $error='Pembayaran bulan ini sudah lunas.';
            } elseif($sudah) {
                $upd=$pdo->prepare('UPDATE pembayaran SET tanggal_pembayaran=:tanggal, jumlah_pembayaran=:jumlah WHERE id_pembayaran=:id');
                $upd->execute(['tanggal'=>date('Y-m-d'),'jumlah'=>(float)$p['harga_sewa'],'id'=>$sudah['id_pembayaran']]);
                $success='Konfirmasi pembayaran berhasil dikirim. Pengelola perlu memverifikasi pembayaran tersebut.';
            } else {
                $ins=$pdo->prepare("INSERT INTO pembayaran (id_penghuni,tanggal_pembayaran,periode_sewa,jumlah_pembayaran,status_pembayaran) VALUES (:id,:tanggal,:periode,:jumlah,'belum_bayar')");
                $ins->execute(['id'=>$p['id_penghuni'],'tanggal'=>date('Y-m-d'),'periode'=>$periodeBulan,'jumlah'=>(float)$p['harga_sewa']]);
                $success='Konfirmasi pembayaran berhasil dikirim. Pengelola perlu memverifikasi pembayaran tersebut.';
            }
        } catch(PDOException $e){ $error='Pengajuan pembayaran gagal. Periksa struktur tabel pembayaran.'; error_log($e->getMessage()); }
    }
}
$q=$pdo->prepare('SELECT * FROM pembayaran WHERE id_penghuni=:id ORDER BY id_pembayaran DESC');$q->execute(['id'=>$p['id_penghuni']]);$data=$q->fetchAll();
$current=null; foreach($data as $r){ if($r['periode_sewa']===$periodeBulan || $r['periode_sewa']===$periodeIso){$current=$r;break;} }
$totalLunas=0;$totalBelum=0;$jumlahLunas=0;$jumlahBelum=0;foreach($data as $r){if($r['status_pembayaran']==='lunas'){$jumlahLunas++;$totalLunas+=(float)$r['jumlah_pembayaran'];}else{$jumlahBelum++;$totalBelum+=(float)$r['jumlah_pembayaran'];}}
$tagihanBulanIni=(float)$p['harga_sewa'];
$statusBulanIni=$current['status_pembayaran']??'belum_tercatat';
function ePP($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');} function periodePP($v){$t=strtotime((string)$v);return $t?date('F Y',$t):(string)$v;} function rpPP($v){return 'Rp '.number_format((float)$v,0,',','.');} function tPP($v,$status=''){return $status==='belum_bayar' ? '-' : ($v?date('d M Y',strtotime($v)):'-');}
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pembayaran Saya | KosSpace</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css" rel="stylesheet"><link href="../assets/css/app.css" rel="stylesheet"></head><body><div class="app-shell d-flex"><aside class="sidebar"><a class="brand" href="dashboard.php"><span class="brand-mark"><i class="bi bi-house-heart-fill"></i></span><span>KosSpace</span></a><div class="sidebar-label">Menu penghuni</div><nav class="side-nav"><a href="dashboard.php"><i class="bi bi-grid-1x2-fill"></i>Dashboard</a><a class="active" href="pembayaran.php"><i class="bi bi-wallet2"></i>Pembayaran</a><a href="keluhan.php"><i class="bi bi-chat-square-text"></i>Keluhan</a><a href="ganti_password.php"><i class="bi bi-shield-lock"></i>Pengaturan akun</a></nav><div class="sidebar-footer"><i class="bi bi-shield-check me-1"></i> Portal Penghuni<br>Informasi kos dan layanan penghuni.</div></aside><main class="app-main"><header class="topbar"><div><div class="topbar-kicker">Workspace / Penghuni</div><div class="topbar-title">Pembayaran bulanan</div></div><div class="user-chip"><div class="avatar"><i class="bi bi-person-fill"></i></div><div class="d-none d-sm-block"><div class="user-name"><?=ePP($_SESSION['nama']??'Penghuni')?></div><div class="user-role">Penghuni kos</div></div><a href="../logout.php" class="btn btn-outline-secondary ms-1"><i class="bi bi-box-arrow-right me-1"></i><span class="d-none d-sm-inline">Keluar</span></a></div></header><section class="page-heading"><div><div class="eyebrow">Keuangan</div><h1>Pembayaran Saya</h1><p>Lihat tagihan bulanan, riwayat pembayaran, dan kirim konfirmasi pembayaran.</p></div></section><?php if($success):?><div class="alert alert-success"><i class="bi bi-check-circle me-2"></i><?=ePP($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><i class="bi bi-exclamation-circle me-2"></i><?=ePP($error)?></div><?php endif;?><section class="row g-3 mb-4"><div class="col-md-4"><div class="stat-card"><div class="stat-top"><span class="stat-label">Tagihan bulan ini</span><span class="stat-icon icon-orange"><i class="bi bi-calendar-month"></i></span></div><div class="stat-value" style="font-size:24px"><?=rpPP($tagihanBulanIni)?></div><div class="stat-foot"><?=ePP($periodeBulan)?></div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-top"><span class="stat-label">Total sudah lunas</span><span class="stat-icon icon-green"><i class="bi bi-check-circle"></i></span></div><div class="stat-value" style="font-size:24px"><?=rpPP($totalLunas)?></div><div class="stat-foot"><?=$jumlahLunas?> transaksi</div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-top"><span class="stat-label">Total belum lunas</span><span class="stat-icon icon-blue"><i class="bi bi-clock"></i></span></div><div class="stat-value" style="font-size:24px"><?=rpPP($totalBelum)?></div><div class="stat-foot"><?=$jumlahBelum?> transaksi</div></div></div></section><section class="panel mb-4"><div class="d-flex flex-column flex-md-row justify-content-between align-items-md-center gap-3"><div><h2 class="panel-title">Tagihan <?=ePP($periodeBulan)?></h2><div class="panel-subtitle">Kamar <?=ePP($p['nomor_kamar']??'-')?> · Tarif <?=rpPP($p['harga_sewa'])?> per bulan.</div></div><div><?php if($statusBulanIni==='lunas'):?><span class="soft-badge"><i class="bi bi-check-circle"></i>Sudah lunas</span><?php else:?><div class="d-flex flex-column align-items-end gap-2"><span class="soft-badge pending"><i class="bi bi-clock"></i>Belum lunas</span><form method="post"><input type="hidden" name="csrf_token" value="<?=ePP($_SESSION['csrf_token'])?>"><input type="hidden" name="aksi" value="ajukan"><button class="btn btn-primary"><i class="bi bi-send me-2"></i>Konfirmasi Pembayaran</button></form></div><?php endif;?></div></div><div class="divider"></div><div class="d-flex justify-content-between align-items-center"><span class="stat-label">Nominal tagihan</span><strong style="font-size:24px"><?=rpPP($tagihanBulanIni)?></strong></div><div class="form-hint mt-3">Fitur ini bukan pembayaran online. Penghuni mengirim konfirmasi pembayaran, lalu pengelola memverifikasi dan mengubah status menjadi lunas.</div></section><section class="panel"><div class="mb-4"><h2 class="panel-title">Riwayat transaksi</h2><div class="panel-subtitle">Seluruh pembayaran yang terkait dengan akunmu.</div></div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>No.</th><th>Periode</th><th>Tanggal</th><th>Jumlah</th><th>Status</th></tr></thead><tbody><?php if(!$data):?><tr><td colspan="5"><div class="empty-state"><i class="bi bi-wallet2"></i><strong class="d-block text-dark mb-1">Belum ada riwayat pembayaran</strong><span>Riwayat akan muncul setelah pembayaran dicatat atau dikonfirmasi.</span></div></td></tr><?php else:foreach($data as $i=>$r):?><tr><td><?=$i+1?></td><td class="fw-semibold"><?=ePP(periodePP($r['periode_sewa']))?></td><td><?=tPP($r['tanggal_pembayaran'],$r['status_pembayaran'])?></td><td class="fw-semibold"><?=rpPP($r['jumlah_pembayaran'])?></td><td><?php if($r['status_pembayaran']==='lunas'):?><span class="soft-badge"><i class="bi bi-check-circle"></i>Lunas</span><?php else:?><span class="soft-badge pending"><i class="bi bi-clock"></i>Belum lunas</span><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section><footer class="app-footer">&copy; <?=date('Y')?> KosSpace · Sistem Informasi Pengelolaan Kos Mahasiswa</footer></main></div></body></html>
